/* ===== V25 apps (2/2): Calendar, Clock, Spreadsheet, Presentations, Contacts, Weather, Characters & Emoji, Event Viewer,
   Camera, Voice Recorder, Fonts, Developer Console, WASI programs, Unix commands + pkg in the Prompt, Save as PDF / print ===== */
/* ===================== Calendar ===================== */
regApp('calendar',{name:'Calendar',icon:'📅',kw:'calendar events reminders agenda',open:()=>calendarApp(),re:/^Calendar/});
const CALK=()=>'bd95cal:'+uid();window.calEvents=()=>USER?ld(CALK(),[]):[];
setInterval(()=>{if(!USER)return;const ev=calEvents(),now=Date.now();let ch=false;ev.forEach(e=>{if(!e.t||e.done)return;const at=new Date(e.d+'T'+e.t).getTime()-(+e.rem||0)*60000;if(now>=at&&now-at<3600000){e.done=1;ch=true;notify('📅 '+e.title,(e.rem?'In '+e.rem+' minutes · ':'')+e.d+' '+e.t,{action:()=>launch('calendar')});try{sfx('notify')}catch(x){}}});if(ch)svj(CALK(),ev)},30000);
function calendarApp(){const W=appWin('calendar','Calendar','📅',720,520);const t=sysNow?sysNow():new Date();let y=t.getFullYear(),m=t.getMonth(),sel=t.toISOString().slice(0,10);
 W.body.style.cssText='display:flex;background:var(--wbg,#fff)';W.body.innerHTML=`<div style='flex:2;padding:8px;display:flex;flex-direction:column'><div class='fh'><button class='p' aria-label='Previous month'>◀</button><button class='td'>Today</button><b class='mt' style='flex:1;text-align:center'></b><button class='n' aria-label='Next month'>▶</button></div><table class='calbig'></table></div><div class='cside' style='flex:1;border-left:1px solid var(--bd);padding:8px;overflow:auto'></div>`;
 const q=s=>W.body.querySelector(s);
 function draw(){const f=new Date(y,m,1),st=(f.getDay()+6)%7,n=new Date(y,m+1,0).getDate(),ev=calEvents();q('.mt').textContent=f.toLocaleDateString([], {month:'long',year:'numeric'});
  let h='<tr>'+['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<th>${x}</th>`).join('')+'</tr><tr>';for(let i=0;i<st;i++)h+='<td></td>';
  for(let d=1;d<=n;d++){const k=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;const es=ev.filter(e=>e.d==k);h+=`<td data-d='${k}' tabindex='0' class='${k==sel?'sel':''} ${k==new Date().toISOString().slice(0,10)?'tod':''}'><div class='cd'>${d}</div>${es.slice(0,3).map(e=>`<div class='ce'>${esc2((e.t||'')+' '+e.title)}</div>`).join('')}${es.length>3?`<div class='ce'>+${es.length-3}</div>`:''}</td>`;if((st+d)%7==0)h+='</tr><tr>'}
  q('.calbig').innerHTML=h+'</tr>';q('.calbig').querySelectorAll('td[data-d]').forEach(td=>{td.onclick=()=>{sel=td.dataset.d;draw()};td.ondblclick=()=>edit({d:td.dataset.d});td.onkeydown=e=>{if(e.key=='Enter')edit({d:td.dataset.d})}});side()}
 function side(){const s=q('.cside');const ev=calEvents().filter(e=>e.d==sel).sort((a,b)=>(a.t||'').localeCompare(b.t||''));s.innerHTML=`<b>${new Date(sel+'T12:00').toLocaleDateString([], {weekday:'long',month:'long',day:'numeric'})}</b><div class='cl'></div><button class='ad'>＋ New event</button>`;
  const l=s.querySelector('.cl');if(!ev.length)l.innerHTML='<div style="opacity:.6;margin:8px 0">No events.</div>';ev.forEach(e=>{const d=document.createElement('div');d.className='acr';d.innerHTML='<span></span><button>Edit</button>';d.firstChild.textContent=(e.t||'All day')+' — '+e.title;d.lastChild.onclick=()=>edit(e);l.appendChild(d)});s.querySelector('.ad').onclick=()=>edit({d:sel})}
 function edit(e){const o=document.createElement('div');o.className='rmodal';o.innerHTML=`<div class='rmbox'><h3>${e.title?'Edit event':'New event'}</h3><div class='r2'><label>Title</label><input class='ti'><label>Date</label><input type='date' class='da'><label>Time</label><input type='time' class='tm'><label>Remind me</label><select class='rm'><option value=''>No reminder</option><option value='0'>At the start</option><option value='5'>5 minutes before</option><option value='15'>15 minutes before</option><option value='60'>1 hour before</option><option value='1440'>1 day before</option></select><label>Notes</label><textarea class='no' rows='3'></textarea></div><div class='rmrow'>${e.title?"<button class='de'>Delete</button>":''}<button class='c'>Cancel</button><button class='ok pri'>Save</button></div></div>`;document.body.appendChild(o);
  const g=s=>o.querySelector(s);g('.ti').value=e.title||'';g('.da').value=e.d;g('.tm').value=e.t||'';g('.rm').value=e.rem==null?'':e.rem;g('.no').value=e.notes||'';g('.ti').focus();
  const all=calEvents();g('.ok').onclick=()=>{if(!g('.ti').value.trim())return g('.ti').focus();const n={id:e.id||Date.now(),title:g('.ti').value.trim(),d:g('.da').value,t:g('.tm').value,rem:g('.rm').value===''?null:+g('.rm').value,notes:g('.no').value};svj(CALK(),[...all.filter(x=>x.id!==e.id),n]);o.remove();sel=n.d;draw()};
  g('.c').onclick=()=>o.remove();if(g('.de'))g('.de').onclick=()=>{svj(CALK(),all.filter(x=>x.id!==e.id));o.remove();draw()};o.addEventListener('keydown',ev=>ev.stopPropagation())}
 q('.p').onclick=()=>{m--;if(m<0){m=11;y--}draw()};q('.n').onclick=()=>{m++;if(m>11){m=0;y++}draw()};q('.td').onclick=()=>{const d=new Date();y=d.getFullYear();m=d.getMonth();sel=d.toISOString().slice(0,10);draw()};
 window.__calGo=d=>{sel=d;y=+d.slice(0,4);m=+d.slice(5,7)-1;draw()};draw();return W}
/* ===================== Clock: alarms, timers, stopwatch, world clocks ===================== */
regApp('clock',{name:'Clock',icon:'⏰',kw:'alarm timer stopwatch world clock time zone',open:()=>clockApp(),re:/^Clock/});
const ALK=()=>'bd95alarms:'+uid();let TIMERS=[];
setInterval(()=>{if(!USER)return;const n=sysNow?sysNow():new Date(),hm=String(n.getHours()).padStart(2,'0')+':'+String(n.getMinutes()).padStart(2,'0'),day=n.getDay(),key=n.toDateString()+hm;let ch=false;
 ld(ALK(),[]).forEach(a=>{if(a.on&&a.t==hm&&(!a.days||!a.days.length||a.days.includes(day))&&a.last!==key){a.last=key;ch=true;alarmRing(a.label||'Alarm',hm)}});if(ch){const l=ld(ALK(),[]).map(a=>a.t==hm?{...a,last:key,on:a.days&&a.days.length?a.on:false}:a);svj(ALK(),l)}
 TIMERS.forEach(t=>{if(!t.done&&Date.now()>=t.end){t.done=1;alarmRing(t.label||'Timer','Time is up')}})},1000);
function alarmRing(t,b){notify('⏰ '+t,b,{kind:'error',toast:15000});let i=0;const iv=setInterval(()=>{try{sfx('notify')}catch(e){}if(++i>8)clearInterval(iv)},900)}
function clockApp(){const W=appWin('clock','Clock','⏰',520,440);let tab='alarm',sw={on:false,acc:0,t0:0,laps:[]},iv;
 W.body.style.cssText='display:flex;flex-direction:column;background:var(--wbg,#fff)';W.body.innerHTML=`<div class='tmtabs'><button data-t='alarm'>Alarms</button><button data-t='timer'>Timers</button><button data-t='sw'>Stopwatch</button><button data-t='world'>World clock</button></div><div class='clb' style='flex:1;overflow:auto;padding:10px'></div>`;
 const B=W.body.querySelector('.clb');W.body.querySelectorAll('.tmtabs button').forEach(b=>b.onclick=()=>{tab=b.dataset.t;draw()});
 const fmt=ms=>{const s=Math.max(0,ms/1000);return`${String(Math.floor(s/3600)).padStart(2,'0')}:${String(Math.floor(s%3600/60)).padStart(2,'0')}:${String(Math.floor(s%60)).padStart(2,'0')}.${String(Math.floor(ms%1000/100))}`};
 function draw(){W.body.querySelectorAll('.tmtabs button').forEach(b=>b.classList.toggle('on',b.dataset.t==tab));B.innerHTML='';
  if(tab=='alarm'){const l=ld(ALK(),[]);const add=document.createElement('div');add.innerHTML=`<input type='time' class='at' value='07:00'> <input class='al' placeholder='Label' style='width:140px'> ${['Su','Mo','Tu','We','Th','Fr','Sa'].map((d,i)=>`<label class='ck'><input type='checkbox' value='${i}'>${d}</label>`).join('')} <button class='aa'>Add alarm</button>`;B.appendChild(add);
   add.querySelector('.aa').onclick=()=>{const days=[...add.querySelectorAll('input[type=checkbox]:checked')].map(c=>+c.value);svj(ALK(),[...l,{t:add.querySelector('.at').value,label:add.querySelector('.al').value,days,on:true}]);draw()};
   l.forEach((a,i)=>{const r=document.createElement('div');r.className='acr';r.innerHTML=`<span style='font-size:22px'></span><span class='lb' style='flex:1'></span><label class='ck'><input type='checkbox'${a.on?' checked':''}> On</label><button>Delete</button>`;r.children[0].textContent=a.t;r.querySelector('.lb').textContent=(a.label||'Alarm')+(a.days&&a.days.length?' · '+a.days.map(d=>'SMTWTFS'[d]).join(''):' · once');
    r.querySelector('input').onchange=e=>{l[i].on=e.target.checked;svj(ALK(),l)};r.querySelector('button').onclick=()=>{l.splice(i,1);svj(ALK(),l);draw()};B.appendChild(r)})}
  else if(tab=='timer'){const add=document.createElement('div');add.innerHTML=`<input type='number' class='tm' value='5' min='0' style='width:60px'> min <input type='number' class='ts' value='0' min='0' max='59' style='width:60px'> s <input class='tl' placeholder='Label' style='width:120px'> <button class='ta'>Start timer</button>`;B.appendChild(add);
   add.querySelector('.ta').onclick=()=>{const ms=(+add.querySelector('.tm').value*60+ +add.querySelector('.ts').value)*1000;if(ms<=0)return;TIMERS.push({end:Date.now()+ms,label:add.querySelector('.tl').value||'Timer',total:ms});draw()};
   const box=document.createElement('div');B.appendChild(box);const upd=()=>{box.innerHTML='';TIMERS.forEach((t,i)=>{const r=document.createElement('div');r.className='acr';r.innerHTML=`<span style='font-size:22px'></span><span style='flex:1'></span><button>Remove</button>`;r.children[0].textContent=t.done?'Done':fmt(t.end-Date.now()).slice(0,8);r.children[1].textContent=t.label;r.querySelector('button').onclick=()=>{TIMERS.splice(i,1);upd()};box.appendChild(r)})};upd();clearInterval(iv);iv=setInterval(upd,500)}
  else if(tab=='sw'){const d=document.createElement('div');d.style.textAlign='center';d.innerHTML=`<div class='swt' style='font:48px monospace;margin:20px'></div><button class='ss pri'></button> <button class='lp'>Lap</button> <button class='rs'>Reset</button><ol class='laps' style='text-align:left'></ol>`;B.appendChild(d);
   const cur=()=>sw.acc+(sw.on?Date.now()-sw.t0:0);const upd=()=>{d.querySelector('.swt').textContent=fmt(cur());d.querySelector('.ss').textContent=sw.on?'Stop':'Start';d.querySelector('.laps').innerHTML=sw.laps.map(x=>`<li>${fmt(x)}</li>`).join('')};
   d.querySelector('.ss').onclick=()=>{if(sw.on){sw.acc=cur();sw.on=false}else{sw.t0=Date.now();sw.on=true}upd()};d.querySelector('.lp').onclick=()=>{sw.laps.unshift(cur());upd()};d.querySelector('.rs').onclick=()=>{sw={on:false,acc:0,t0:0,laps:[]};upd()};upd();clearInterval(iv);iv=setInterval(upd,100)}
  else{const Z=ld('bd95world:'+uid(),['America/New_York','Europe/London','Asia/Tokyo']);const add=document.createElement('div');let opts='';try{opts=Intl.supportedValuesOf('timeZone').map(z=>`<option>${z}</option>`).join('')}catch(e){}add.innerHTML=`<select class='wz' style='max-width:260px'>${opts}</select> <button class='wa'>Add city</button>`;B.appendChild(add);
   add.querySelector('.wa').onclick=()=>{svj('bd95world:'+uid(),[...Z,add.querySelector('.wz').value]);draw()};const box=document.createElement('div');B.appendChild(box);
   const upd=()=>{box.innerHTML='';Z.forEach((z,i)=>{const r=document.createElement('div');r.className='acr';let tm='';try{tm=new Date().toLocaleTimeString([], {timeZone:z,hour:'2-digit',minute:'2-digit',weekday:'short'})}catch(e){}r.innerHTML=`<span style='font-size:20px;width:140px'></span><span style='flex:1'></span><button>Remove</button>`;r.children[0].textContent=tm;r.children[1].textContent=z.replace(/_/g,' ');r.querySelector('button').onclick=()=>{Z.splice(i,1);svj('bd95world:'+uid(),Z);draw()};box.appendChild(r)})};upd();clearInterval(iv);iv=setInterval(upd,10000)}}
 W.onclose=()=>clearInterval(iv);draw();return W}
/* ===================== Spreadsheet ===================== */
regApp('sheet',{name:'Spreadsheet',icon:'📊',kw:'spreadsheet table excel csv formulas',open:()=>sheetApp(),openFile:p=>sheetApp(p),re:/^Spreadsheet/});
function sheetApp(path){const W=appWin('sheet','Spreadsheet','📊',820,520);const C=26,R=100;let cells={},sel='A1',file=path||null,dirty=false;
 const col=i=>String.fromCharCode(65+i),idx=a=>{const m=/^([A-Z])(\d+)$/.exec(a);return m?[m[1].charCodeAt(0)-65,+m[2]-1]:null};
 W.body.style.cssText='display:flex;flex-direction:column;background:var(--wbg,#fff)';W.body.innerHTML=`<div class='xb'><button class='op'>Open…</button><button class='sv'>Save</button><button class='sa'>Save as…</button><button class='icsv'>Import CSV…</button><button class='ex'>Export CSV</button><button class='bo' aria-label='Bold'><b>B</b></button><span class='ref' style='min-width:40px;font-weight:600'></span><input class='fx' style='flex:1' aria-label='Formula'></div><div class='shg' style='flex:1;overflow:auto'></div><div class='stat'></div>`;
 const q=s=>W.body.querySelector(s),grid=q('.shg'),fx=q('.fx'),stat=q('.stat');
 const t=document.createElement('table');t.className='sht';let h='<tr><th></th>'+[...Array(C)].map((_,i)=>`<th>${col(i)}</th>`).join('')+'</tr>';for(let r=0;r<R;r++){h+=`<tr><th>${r+1}</th>`+[...Array(C)].map((_,c)=>`<td data-a='${col(c)}${r+1}' tabindex='-1'></td>`).join('')+'</tr>'}t.innerHTML=h;grid.appendChild(t);
 function val(a,stack){stack=stack||new Set();if(stack.has(a))return'#CYCLE';const c=cells[a];if(!c||c.v==null||c.v==='')return'';const v=String(c.v);if(v[0]!='=')return isFinite(+v)&&v.trim()!==''?+v:v;stack.add(a);try{return evalF(v.slice(1),stack)}catch(e){return'#ERR'}finally{stack.delete(a)}}
 function range(a,b,stack){const A=idx(a),B=idx(b);const out=[];for(let r=Math.min(A[1],B[1]);r<=Math.max(A[1],B[1]);r++)for(let c=Math.min(A[0],B[0]);c<=Math.max(A[0],B[0]);c++)out.push(val(col(c)+(r+1),stack));return out}
 const FN={SUM:a=>a.flat().filter(x=>typeof x=='number').reduce((s,x)=>s+x,0),AVERAGE:a=>{const n=a.flat().filter(x=>typeof x=='number');return n.length?n.reduce((s,x)=>s+x,0)/n.length:0},MIN:a=>Math.min(...a.flat().filter(x=>typeof x=='number')),MAX:a=>Math.max(...a.flat().filter(x=>typeof x=='number')),COUNT:a=>a.flat().filter(x=>typeof x=='number').length,ROUND:a=>{const p=10**(a[1]||0);return Math.round(a[0]*p)/p},ABS:a=>Math.abs(a[0]),IF:a=>a[0]?a[1]:a[2],CONCAT:a=>a.flat().join(''),SQRT:a=>Math.sqrt(a[0]),POWER:a=>a[0]**a[1]};
 function evalF(src,stack){let s=src.toUpperCase().replace(/\$/g,'');const vals=[];s=s.replace(/([A-Z]\d+):([A-Z]\d+)/g,(m,a,b)=>{vals.push(range(a,b,stack));return`__v[${vals.length-1}]`});
  s=s.replace(/\b([A-Z])(\d+)\b/g,(m)=>{const v=val(m,stack);vals.push(v);return`__v[${vals.length-1}]`});
  s=s.replace(/\b(SUM|AVERAGE|MIN|MAX|COUNT|ROUND|ABS|IF|CONCAT|SQRT|POWER)\(/g,'__f.$1(');s=s.replace(/__f\.(\w+)\(([^()]*)\)/g,'__f.$1([$2])').replace(/<>/g,'!=').replace(/([^<>!=])=([^=])/g,'$1==$2');
  if(/[^\d\s+\-*/().,<>=!&|?:_\[\]a-zA-Z"']/.test(s.replace(/__[vf]/g,'')))throw 0;return Function('__v','__f','"use strict";return('+s+')')(vals,FN)}
 function render(){t.querySelectorAll('td').forEach(td=>{const a=td.dataset.a,c=cells[a];const v=c?val(a):'';td.textContent=typeof v=='number'?(Math.round(v*1e9)/1e9).toLocaleString():v;td.style.fontWeight=c&&c.b?'700':'';td.classList.toggle('num',typeof v=='number');td.classList.toggle('sel',a==sel)});q('.ref').textContent=sel;fx.value=cells[sel]?cells[sel].v:'';stat.textContent=(file?file.join('\\'):'Untitled')+(dirty?' • modified':'')}
 const setC=(a,v)=>{if(v===''&&!(cells[a]&&cells[a].b))delete cells[a];else cells[a]=Object.assign(cells[a]||{},{v});dirty=true};
 function move(dc,dr){const p=idx(sel);sel=col(Math.max(0,Math.min(C-1,p[0]+dc)))+Math.max(1,Math.min(R,p[1]+1+dr));render();const td=t.querySelector(`td[data-a='${sel}']`);td.focus();td.scrollIntoView({block:'nearest',inline:'nearest'})}
 t.onclick=e=>{const td=e.target.closest('td');if(!td)return;sel=td.dataset.a;render();td.focus()};t.ondblclick=e=>{fx.focus()};
 t.onkeydown=e=>{const k=e.key;if(k=='ArrowUp')move(0,-1);else if(k=='ArrowDown'||k=='Enter')move(0,1);else if(k=='ArrowLeft')move(-1,0);else if(k=='ArrowRight'||k=='Tab')move(1,0);else if(k=='Delete'||k=='Backspace'){setC(sel,'');render()}else if(k=='F2'){fx.focus()}else if(k.length==1&&!e.ctrlKey){fx.value=k;fx.focus();e.preventDefault();return}else if(e.ctrlKey&&k=='s'){e.preventDefault();save()}else return;e.preventDefault()};
 fx.onkeydown=e=>{e.stopPropagation();if(e.key=='Enter'){setC(sel,fx.value);render();move(0,1)}if(e.key=='Escape'){render();t.querySelector(`td[data-a='${sel}']`).focus()}};
 const toCSV=()=>{let maxR=0,maxC=0;for(const a in cells){const p=idx(a);maxR=Math.max(maxR,p[1]);maxC=Math.max(maxC,p[0])}let o='';for(let r=0;r<=maxR;r++){const row=[];for(let c=0;c<=maxC;c++){const v=String(val(col(c)+(r+1)));row.push(/[",\n]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v)}o+=row.join(',')+'\n'}return o};
 const fromCSV=s=>{cells={};const rows=[];let row=[],f='',qd=false;for(let i=0;i<s.length;i++){const c=s[i];if(qd){if(c=='"'&&s[i+1]=='"'){f+='"';i++}else if(c=='"')qd=false;else f+=c}else if(c=='"')qd=true;else if(c==','){row.push(f);f=''}else if(c=='\n'){row.push(f);rows.push(row);row=[];f=''}else if(c!='\r')f+=c}if(f||row.length){row.push(f);rows.push(row)}rows.slice(0,R).forEach((r,ri)=>r.slice(0,C).forEach((v,ci)=>{if(v!=='')cells[col(ci)+(ri+1)]={v}}))};
 function load(p){const v=node(p);if(typeof v!='string')return;if(ext(p.at(-1))=='CSV')fromCSV(v);else{try{cells=JSON.parse(v).cells||{}}catch(e){cells={}}}file=p;dirty=false;W.setTitle('Spreadsheet - '+p.at(-1));recentAdd(p);render()}
 async function save(as){let p=file;if(!p||as||ext(p.at(-1))=='CSV'&&as!==false){p=await saveVfsDlg(file?file.at(-1).replace(/\.CSV$/i,'.RSHEET'):'BOOK.RSHEET');if(!p)return}vfsWrite(p,ext(p.at(-1))=='CSV'?toCSV():JSON.stringify({v:1,cells}));file=p;dirty=false;render();notify('Saved',p.join('\\'),{quiet:true})}
 q('.op').onclick=async()=>{const p=await pickVfsFile('Open a spreadsheet',n=>/\.(RSHEET|CSV)$/i.test(n));p&&load(p)};q('.sv').onclick=()=>save(false);q('.sa').onclick=()=>save(true);
 q('.icsv').onclick=async()=>{const p=await pickVfsFile('Import a CSV file',n=>/\.CSV$/i.test(n));if(p){fromCSV(node(p));dirty=true;render()}};q('.ex').onclick=()=>saveOut((file?file.at(-1).replace(/\.[^.]*$/,''):'sheet')+'.csv',toCSV(),'text/csv');
 q('.bo').onclick=()=>{cells[sel]=cells[sel]||{v:''};cells[sel].b=!cells[sel].b;dirty=true;render()};
 if(path)load(path);else render();setTimeout(()=>t.querySelector('td').focus(),30);return W}
/* ===================== Presentations ===================== */
regApp('deck',{name:'Presentations',icon:'📽️',kw:'slides presentation slideshow powerpoint',open:()=>deckApp(),openFile:p=>deckApp(p),re:/^Presentations/});
function deckApp(path){const W=appWin('deck','Presentations','📽️',860,540);let D={slides:[{title:'Title of your talk',body:'Your name\nDate',bg:'#1e3a8a',fg:'#ffffff',img:null}]},i=0,file=path||null;
 W.body.style.cssText='display:flex;flex-direction:column;background:var(--wbg,#fff)';W.body.innerHTML=`<div class='xb'><button class='op'>Open…</button><button class='sv'>Save</button><button class='ad'>＋ Slide</button><button class='du'>Duplicate</button><button class='de'>Delete</button><button class='up'>▲</button><button class='dn'>▼</button><label>Background <input type='color' class='bg'></label><label>Text <input type='color' class='fg'></label><button class='im'>Picture…</button><button class='pr pri'>▶ Present</button><button class='pdf'>Save as PDF</button></div><div style='flex:1;display:flex;min-height:0'><div class='dl' style='width:150px;overflow:auto;border-right:1px solid var(--bd)'></div><div style='flex:1;display:flex;flex-direction:column;padding:10px;gap:6px'><input class='ti' placeholder='Slide title' style='font-size:18px'><textarea class='bd' placeholder='One point per line' style='flex:1'></textarea></div></div>`;
 const q=s=>W.body.querySelector(s);const S1=()=>D.slides[i];
 const slideEl=(s,w)=>{const d=document.createElement('div');d.className='dsl';d.style.cssText=`width:${w}px;height:${w*9/16}px;background:${s.bg} ${s.img?`url("${s.img}") center/cover`:''};color:${s.fg};font-size:${w/24}px`;d.innerHTML='<h1></h1><ul></ul>';d.querySelector('h1').textContent=s.title;s.body.split('\n').filter(Boolean).forEach(l=>{const li=document.createElement('li');li.textContent=l;d.querySelector('ul').appendChild(li)});return d};
 function draw(){const l=q('.dl');l.innerHTML='';D.slides.forEach((s,k)=>{const w=document.createElement('div');w.className='dth'+(k==i?' on':'');w.tabIndex=0;w.appendChild(slideEl(s,128));w.onclick=()=>{i=k;draw()};l.appendChild(w)});const s=S1();q('.ti').value=s.title;q('.bd').value=s.body;q('.bg').value=s.bg;q('.fg').value=s.fg}
 q('.ti').oninput=e=>{S1().title=e.target.value;draw2()};q('.bd').oninput=e=>{S1().body=e.target.value;draw2()};const draw2=()=>{const th=q('.dl').children[i];th&&th.replaceChildren(slideEl(S1(),128))};
 q('.bg').oninput=e=>{S1().bg=e.target.value;draw2()};q('.fg').oninput=e=>{S1().fg=e.target.value;draw2()};
 q('.ad').onclick=()=>{D.slides.splice(i+1,0,{title:'New slide',body:'',bg:S1().bg,fg:S1().fg,img:null});i++;draw()};q('.du').onclick=()=>{D.slides.splice(i+1,0,JSON.parse(JSON.stringify(S1())));i++;draw()};
 q('.de').onclick=()=>{if(D.slides.length>1){D.slides.splice(i,1);i=Math.max(0,i-1);draw()}};q('.up').onclick=()=>{if(i>0){[D.slides[i-1],D.slides[i]]=[D.slides[i],D.slides[i-1]];i--;draw()}};q('.dn').onclick=()=>{if(i<D.slides.length-1){[D.slides[i+1],D.slides[i]]=[D.slides[i],D.slides[i+1]];i++;draw()}};
 q('.im').onclick=async()=>{const p=await pickVfsFile('Choose a picture',(n,v)=>typeof v=='string'&&v.startsWith('data:image'));S1().img=p?node(p):null;draw()};
 q('.op').onclick=async()=>{const p=await pickVfsFile('Open a presentation',n=>/\.RDECK$/i.test(n));p&&load(p)};
 q('.sv').onclick=async()=>{let p=file;if(!p){p=await saveVfsDlg('PRESENTATION.RDECK');if(!p)return}vfsWrite(p,JSON.stringify(D));file=p;W.setTitle('Presentations - '+p.at(-1));notify('Saved',p.join('\\'),{quiet:true})};
 q('.pr').onclick=()=>{let k=i;const o=document.createElement('div');o.id='present';o.tabIndex=0;const show=()=>{o.replaceChildren(slideEl(D.slides[k],Math.min(innerWidth,innerHeight*16/9)))};show();document.body.appendChild(o);o.focus();try{o.requestFullscreen&&o.requestFullscreen().catch(()=>{})}catch(e){}
  const end=()=>{o.remove();if(document.fullscreenElement)document.exitFullscreen().catch(()=>{})};o.onkeydown=e=>{e.stopPropagation();if(['ArrowRight','PageDown',' ','Enter'].includes(e.key)){if(k<D.slides.length-1){k++;show()}else end()}else if(['ArrowLeft','PageUp','Backspace'].includes(e.key)){if(k>0){k--;show()}}else if(e.key=='Escape')end()};o.onclick=()=>{if(k<D.slides.length-1){k++;show()}else end()}};
 q('.pdf').onclick=async()=>{const pages=[];for(const s of D.slides){const c=document.createElement('canvas');c.width=1280;c.height=720;const g=c.getContext('2d');g.fillStyle=s.bg;g.fillRect(0,0,1280,720);if(s.img){const im=new Image();im.src=s.img;await im.decode().catch(()=>{});try{g.drawImage(im,0,0,1280,720)}catch(e){}}g.fillStyle=s.fg;g.font='bold 56px sans-serif';g.fillText(s.title,60,120);g.font='34px sans-serif';s.body.split('\n').filter(Boolean).forEach((l,j)=>g.fillText('• '+l,80,220+j*56));pages.push(c)}
  const pdf=pdfFromCanvases(pages,1280*0.6,720*0.6);savePdf((file?file.at(-1).replace(/\.[^.]*$/,''):'PRESENTATION')+'.PDF',pdf)};
 function load(p){try{D=JSON.parse(node(p));file=p;i=0;W.setTitle('Presentations - '+p.at(-1));recentAdd(p);draw()}catch(e){notify('Not a presentation','',{kind:'error'})}}
 if(path)load(path);else draw();return W}
