function contactsApp(){const W=appWin('contacts','Contacts','👥',640,440);const K='bd95contacts:'+uid();let L=ld(K,[]),sel=null,f='';
 W.body.style.cssText='display:flex;background:var(--wbg,#fff)';W.body.innerHTML=`<div style='width:220px;border-right:1px solid var(--bd);display:flex;flex-direction:column'><input class='sr' type='search' placeholder='Search' style='margin:6px'><div class='cl' style='flex:1;overflow:auto'></div><button class='ad' style='margin:6px'>＋ New contact</button></div><div class='cf' style='flex:1;padding:12px;overflow:auto'></div>`;
 const q=s=>W.body.querySelector(s);const F=[['n','Name'],['ph','Phone'],['em','E-mail'],['ad','Address'],['bd','Birthday','date'],['no','Notes']];
 function list(){const l=q('.cl');l.innerHTML='';L.filter(c=>!f||JSON.stringify(c).toLowerCase().includes(f)).sort((a,b)=>a.n.localeCompare(b.n)).forEach(c=>{const d=document.createElement('div');d.className='pkr'+(c===sel?' on':'');d.tabIndex=0;d.textContent='👤 '+c.n;d.onclick=()=>{sel=c;list();form()};l.appendChild(d)})}
 function form(){const b=q('.cf');if(!sel){b.innerHTML='<div style="opacity:.6">Choose or add a contact.</div>';return}b.innerHTML=`<div class='r2'>${F.map(([k,l,t])=>`<label>${l}</label>${k=='no'||k=='ad'?`<textarea data-k='${k}' rows='2'></textarea>`:`<input data-k='${k}' type='${t||'text'}'>`}`).join('')}</div><div class='rmrow'><button class='de'>Delete</button><button class='em'>Write e-mail</button><button class='ok pri'>Save</button></div>`;
  b.querySelectorAll('[data-k]').forEach(i=>i.value=sel[i.dataset.k]||'');b.querySelector('.ok').onclick=()=>{b.querySelectorAll('[data-k]').forEach(i=>sel[i.dataset.k]=i.value);if(!sel.n)sel.n='(no name)';if(!L.includes(sel))L.push(sel);svj(K,L);list()};
  b.querySelector('.de').onclick=()=>{L=L.filter(x=>x!==sel);svj(K,L);sel=null;list();form()};b.querySelector('.em').onclick=()=>{if(sel.em)emailCompose({to:sel.em})}}
 q('.ad').onclick=()=>{sel={n:''};form();q('.cf input').focus()};q('.sr').oninput=e=>{f=e.target.value.toLowerCase();list()};list();form();return W}
