function weatherApp(){const W=appWin('weather','Weather','⛅',520,440);W.body.style.cssText='padding:12px;overflow:auto;background:linear-gradient(#e0f2fe,#fff)';
 W.body.innerHTML=`<div style='display:flex;gap:6px'><input class='c' placeholder='City' style='flex:1'><button class='go'>Search</button></div><div class='wr' style='margin-top:10px'></div><div class='msg' style='color:#6b7280;font-size:12px'>Forecast data: Open-Meteo.com (needs an internet connection).</div>`;
 const q=s=>W.body.querySelector(s);const box=q('.wr');
 async function show(loc){box.textContent='Loading…';try{const r=await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${loc.lat}&longitude=${loc.lon}&current=temperature_2m,weather_code,wind_speed_10m,relative_humidity_2m&daily=weather_code,temperature_2m_max,temperature_2m_min&timezone=auto`);const j=await r.json();
  const ic=c=>c==0?'☀️':c<=2?'🌤️':c==3?'☁️':c<50?'🌫️':c<60?'🌦️':c<70?'🌧️':c<80?'🌨️':c<90?'🌦️':'⛈️';box.innerHTML=`<h2 style='margin:4px 0'></h2><div style='font-size:48px'>${ic(j.current.weather_code)} ${Math.round(j.current.temperature_2m)}°C</div><div>Wind ${Math.round(j.current.wind_speed_10m)} km/h · Humidity ${j.current.relative_humidity_2m}%</div><table class='tmt' style='margin-top:10px'>${j.daily.time.map((d,i)=>`<tr><td>${new Date(d+'T12:00').toLocaleDateString([], {weekday:'long'})}</td><td>${ic(j.daily.weather_code[i])}</td><td>${Math.round(j.daily.temperature_2m_max[i])}° / ${Math.round(j.daily.temperature_2m_min[i])}°</td></tr>`).join('')}</table>`;box.querySelector('h2').textContent=loc.name;svj('bd95wloc',loc)}
  catch(e){box.textContent='Weather is not available right now (no internet connection?).'}}
 q('.go').onclick=async()=>{const n=q('.c').value.trim();if(!n)return;box.textContent='Searching…';try{const r=await fetch('https://geocoding-api.open-meteo.com/v1/search?count=1&name='+encodeURIComponent(n));const j=await r.json();const g=j.results&&j.results[0];if(!g)return box.textContent='City not found.';show({lat:g.latitude,lon:g.longitude,name:g.name+(g.country?', '+g.country:'')})}catch(e){box.textContent='No internet connection.'}};
 q('.c').onkeydown=e=>{e.stopPropagation();if(e.key=='Enter')q('.go').click()};show(ld('bd95wloc',null)||{lat:52.52,lon:13.41,name:'Berlin, Germany'});return W}
