const API_DOC=`Rudolf OS app API (.RAPP packages)
==================================
A .RAPP file is JSON:
 { "id": "com.example.hello", "name": "Hello", "icon": "👋", "version": "1.0",
   "description": "…", "permissions": ["notifications","files","clipboard"],
   "html": "<h1>Hello</h1><script>rudolf.notify('Hi','from my app')<\/script>" }
The page runs in a sandboxed frame. It talks to Rudolf OS through window.rudolf:
 rudolf.notify(title, body)            → shows a notification (needs "notifications")
 rudolf.setTitle(text)                 → window title
 rudolf.storage.get(key) / .set(key,v) → small per-user storage for the app
 rudolf.files.open()                   → user picks a file; {name,text,dataURL} (needs "files")
 rudolf.files.save(name, text)         → user picks where to save (needs "files")
 rudolf.clipboard.read() / .write(t)   → clipboard (read needs "clipboard")
 rudolf.user()                         → {name, language}
 rudolf.theme()                        → {dark, accent}
All calls return promises. Ask only for the permissions you need; users are asked once.
Make a package with Code Editor → "Package as app", install it from the App Store or by opening the file.

Lua (Rudolf Prompt, BlockLua): see Help → Developers for the js, gl and quake libraries.
Unix-style commands in the Prompt: ls cat grep head tail wc sort uniq echo cp mv rm mkdir touch pwd find tree clear,
pipes (a | b) and redirection (> file, >> file). Package manager: pkg list | pkg install NAME | pkg remove NAME.
WebAssembly: open a .WASM file or type  wasm FILE.WASM args  (WASI preview 1, standard output only).`;
/* ===================== WebAssembly (WASI) programs ===================== */
async function wasiRun(path,args,P){const bin=node(path);if(typeof bin!='string')return P&&P.print('File not found');P=P||prompt();const bytes=new Uint8Array(await dataToBlob(bin).arrayBuffer());let mem,out='';
 const enc=new TextEncoder(),dec=new TextDecoder();const argv=[path.at(-1),...(args||[])];const env=['HOME=/','USER='+(USER?USER.n:'')];
 const flush=(s)=>{out+=s;let i;while((i=out.indexOf('\n'))>=0){P.print(out.slice(0,i));out=out.slice(i+1)}};
 class Exit{constructor(c){this.c=c}}
 const strs=(list,ptrs,buf)=>{const m=new DataView(mem.buffer),u=new Uint8Array(mem.buffer);let o=buf;list.forEach((s,i)=>{m.setUint32(ptrs+i*4,o,true);const b=enc.encode(s+'\0');u.set(b,o);o+=b.length});return 0};
 const sizes=(list,cnt,sz)=>{const m=new DataView(mem.buffer);m.setUint32(cnt,list.length,true);m.setUint32(sz,list.reduce((a,s)=>a+enc.encode(s).length+1,0),true);return 0};
 const W={args_get:(p,b)=>strs(argv,p,b),args_sizes_get:(c,s)=>sizes(argv,c,s),environ_get:(p,b)=>strs(env,p,b),environ_sizes_get:(c,s)=>sizes(env,c,s),
  fd_write:(fd,iov,n,nw)=>{const m=new DataView(mem.buffer);let t=0;for(let i=0;i<n;i++){const p=m.getUint32(iov+i*8,true),l=m.getUint32(iov+i*8+4,true);flush(dec.decode(new Uint8Array(mem.buffer,p,l)));t+=l}m.setUint32(nw,t,true);return 0},
  fd_read:(fd,iov,n,nr)=>{new DataView(mem.buffer).setUint32(nr,0,true);return 0},fd_close:()=>0,fd_seek:()=>70,fd_fdstat_get:(fd,p)=>{const m=new DataView(mem.buffer);m.setUint8(p,fd<3?2:4);return 0},fd_prestat_get:()=>8,fd_prestat_dir_name:()=>8,path_open:()=>76,
  clock_time_get:(id,pr,p)=>{new DataView(mem.buffer).setBigUint64(p,BigInt(Math.round((id==0?Date.now():performance.now())*1e6)),true);return 0},random_get:(p,l)=>{crypto.getRandomValues(new Uint8Array(mem.buffer,p,l));return 0},proc_exit:c=>{throw new Exit(c)},sched_yield:()=>0,poll_oneoff:()=>52};
 const imp={wasi_snapshot_preview1:new Proxy(W,{get:(t,k)=>t[k]||(()=>52)})};
 try{const {instance}=await WebAssembly.instantiate(bytes,imp);mem=instance.exports.memory;const t0=performance.now();instance.exports._start();if(out)P.print(out);P.print(`[${path.at(-1)} finished in ${Math.round(performance.now()-t0)} ms]`)}catch(e){if(out)P.print(out);if(e instanceof Exit)P.print(`[exit code ${e.c}]`);else P.print('WebAssembly error: '+e.message)}}
/* ===================== Unix commands, pipes and pkg in the Rudolf Prompt ===================== */
